package com.konnectivity.privateapp;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.net.Uri;
import android.os.Bundle;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import java.util.ArrayList;

public class MainActivity extends Activity {
    private static final int BG=Color.rgb(16,26,43), INK=Color.rgb(244,240,237), MUTED=Color.rgb(175,188,210), ACCENT=Color.rgb(247,179,157);
    private android.content.SharedPreferences prefs;
    private WebView web;
    private String trustedOrigin="";
    private ValueCallback<Uri[]> fileResult;
    private PermissionRequest mediaRequest;
    private GeolocationPermissions.Callback locationResult;
    private String locationOrigin;
    private View fullVideo;
    private WebChromeClient.CustomViewCallback fullCallback;
    private LinearLayout shell;
    private String sharedUrl="";
    @Override public void onCreate(Bundle state) { super.onCreate(state); prefs=getSharedPreferences("connection",MODE_PRIVATE); if(Intent.ACTION_SEND.equals(getIntent().getAction()))sharedUrl=getIntent().getStringExtra(Intent.EXTRA_TEXT); showRoles(); }
    private int dp(int value){return (int)(value*getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout view=new LinearLayout(this);view.setOrientation(LinearLayout.VERTICAL);view.setPadding(dp(24),dp(24),dp(24),dp(24));view.setBackgroundColor(BG);return view;}
    private TextView text(String value,int size,int color){TextView view=new TextView(this);view.setText(value);view.setTextSize(size);view.setTextColor(color);view.setPadding(0,dp(10),0,dp(10));return view;}
    private Button button(String title,Runnable action){Button button=new Button(this);button.setText(title);button.setTextColor(BG);button.setBackgroundTintList(android.content.res.ColorStateList.valueOf(ACCENT));button.setAllCaps(false);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,dp(58));params.setMargins(0,dp(10),0,dp(6));button.setLayoutParams(params);button.setOnClickListener(view->action.run());return button;}
    private void display(LinearLayout content){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(content);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(0,insets.getSystemWindowInsetTop(),0,insets.getSystemWindowInsetBottom());return insets;});}
    private void showRoles(){if(web!=null){web.destroy();web=null;}LinearLayout view=column();view.addView(text("Konnectivity",34,INK));view.addView(text("Your people. One soundtrack.",19,MUTED));view.addView(text("How are you joining?",25,INK));view.addView(button("Admin  ·  SuperAdmin console",()->showConnect("Admin")));view.addView(button("Host  ·  Create a group & party",()->showConnect("Host")));view.addView(button("Listener  ·  Join with a room URL",()->showConnect("Listener")));view.addView(text("Connect to your private Konnectivity server. Your account and room permissions stay the same.",15,MUTED));display(view);}
    private EditText field(LinearLayout view,String label,String value){view.addView(text(label,15,MUTED));EditText input=new EditText(this);input.setSingleLine(true);input.setText(value);input.setTextColor(INK);input.setTextSize(17);input.setSelectAllOnFocus(true);view.addView(input,new LinearLayout.LayoutParams(-1,dp(56)));return input;}
    private void showConnect(String role){LinearLayout view=column();view.addView(button("‹ Choose another role",this::showRoles));view.addView(text(role,32,INK));boolean listener=role.equals("Listener");EditText address=field(view,listener?"Full room invitation URL":"Server URL",listener?sharedUrl:prefs.getString("server",""));address.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);EditText name=listener?field(view,"Your name",prefs.getString("name","")):null;TextView error=text("",15,ACCENT);view.addView(error);view.addView(button(listener?"Join room":role.equals("Admin")?"Open SuperAdmin login":"Create a group & party",()->{try {Uri uri=Uri.parse(address.getText().toString().trim());if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw new IllegalArgumentException("Enter a complete HTTPS URL.");String origin="https://"+uri.getEncodedAuthority();String target;if(listener){if(uri.getPath()==null||!uri.getPath().matches("/r/[A-Za-z0-9]{6}/?"))throw new IllegalArgumentException("Paste the full room URL containing /r/ and its code.");String nick=name.getText().toString().trim();if(nick.isEmpty())throw new IllegalArgumentException("Enter your name to join.");if(nick.length()>24)nick=nick.substring(0,24);prefs.edit().putString("name",nick).apply();String fragment=uri.getEncodedFragment();fragment=(fragment==null||fragment.isEmpty()?"":fragment+"&")+"app-join=1&app-name="+Uri.encode(nick);target=uri.buildUpon().fragment(null).encodedFragment(fragment).build().toString();}else target=origin+(role.equals("Admin")?"/admin/login":"/groups");prefs.edit().putString("server",origin).apply();trustedOrigin=origin;openRoom(target);}catch(Exception exception){error.setText(exception.getMessage());}}));display(view);}
    private boolean trusted(String origin){return trustedOrigin.equals(origin);}
    private void openRoom(String url){shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setBackgroundColor(BG);LinearLayout bar=new LinearLayout(this);bar.setPadding(dp(8),0,dp(8),0);Button back=button("‹",()->{if(web.canGoBack())web.goBack();else confirmExit();});bar.addView(back,new LinearLayout.LayoutParams(dp(48),dp(44)));TextView title=text("Konnectivity",16,INK);bar.addView(title,new LinearLayout.LayoutParams(0,dp(44),1));Button roles=button("Roles",this::confirmExit);bar.addView(roles,new LinearLayout.LayoutParams(dp(80),dp(44)));shell.addView(bar);web=new WebView(this);shell.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(shell);shell.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(0,insets.getSystemWindowInsetTop(),0,insets.getSystemWindowInsetBottom());return insets;});WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setMediaPlaybackRequiresUserGesture(false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(true);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,true);
      web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){if(!request.isForMainFrame())return false;Uri target=request.getUrl();String origin=target.getScheme()+"://"+target.getEncodedAuthority();if(trusted(origin))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,target));}catch(Exception ignored){}return true;}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())new AlertDialog.Builder(MainActivity.this).setTitle("Cannot reach your server").setMessage("Keep the laptop server running and check the current share URL.").setPositiveButton("Retry",(dialog,which)->web.reload()).setNegativeButton("Change URL",(dialog,which)->showRoles()).show();}});
      web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(fileResult!=null)fileResult.onReceiveValue(null);fileResult=callback;try{startActivityForResult(params.createIntent(),42);}catch(Exception error){fileResult.onReceiveValue(null);fileResult=null;return false;}return true;}
       @Override public void onPermissionRequest(PermissionRequest request){runOnUiThread(()->{if(!trusted(request.getOrigin().toString().replaceAll("/$",""))){request.deny();return;}mediaRequest=request;ArrayList<String> needed=new ArrayList<>();for(String resource:request.getResources()){if(resource.equals(PermissionRequest.RESOURCE_AUDIO_CAPTURE)&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)needed.add(Manifest.permission.RECORD_AUDIO);if(resource.equals(PermissionRequest.RESOURCE_VIDEO_CAPTURE)&&checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)needed.add(Manifest.permission.CAMERA);}if(needed.isEmpty())grantMedia();else requestPermissions(needed.toArray(new String[0]),43);});}
       @Override public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback callback){if(!trusted(origin.replaceAll("/$",""))){callback.invoke(origin,false,false);return;}locationOrigin=origin;locationResult=callback;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED){callback.invoke(origin,true,false);locationResult=null;}else requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION},44);}
       @Override public void onShowCustomView(View view,CustomViewCallback callback){if(fullVideo!=null){callback.onCustomViewHidden();return;}fullVideo=view;fullCallback=callback;setContentView(view);}
       @Override public void onHideCustomView(){if(fullVideo==null)return;setContentView(shell);fullCallback.onCustomViewHidden();fullVideo=null;}
      });web.loadUrl(url);}
    private void grantMedia(){if(mediaRequest==null)return;ArrayList<String> granted=new ArrayList<>();for(String resource:mediaRequest.getResources()){if(resource.equals(PermissionRequest.RESOURCE_AUDIO_CAPTURE)&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)granted.add(resource);if(resource.equals(PermissionRequest.RESOURCE_VIDEO_CAPTURE)&&checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)granted.add(resource);}mediaRequest.grant(granted.toArray(new String[0]));mediaRequest=null;}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==43)grantMedia();if(request==44&&locationResult!=null){locationResult.invoke(locationOrigin,grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED,false);locationResult=null;}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==42&&fileResult!=null){fileResult.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));fileResult=null;}}
    private void confirmExit(){new AlertDialog.Builder(this).setTitle("Leave this screen?").setMessage("Return to Admin, Host and Listener selection?").setNegativeButton("Stay",null).setPositiveButton("Choose role",(dialog,which)->showRoles()).show();}
    @Override public void onBackPressed(){if(fullVideo!=null){web.getWebChromeClient().onHideCustomView();return;}if(web!=null&&web.canGoBack())web.goBack();else if(web!=null)confirmExit();else super.onBackPressed();}
    @Override protected void onDestroy(){if(fileResult!=null)fileResult.onReceiveValue(null);if(mediaRequest!=null)mediaRequest.deny();if(web!=null)web.destroy();super.onDestroy();}
}
